        "code": "\n#!/usr/bin/env python3\n\"\"\"Misdirection: Part 1. Offline AES-ECB decrypt using recovered admin key.\"\"\"\n\nimport hashlib\nfrom cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes\n\n# Recovered from the WebAuthn admin-bot ECDSA signature.\nPRIVATE_KEY_HEX = 'abf9e91ac6b24259d8523f8d86e7be778484af175d2c3fad389a64510621cdf7'\n\n# Ciphertext provided by the CTF hint.\nCIPHERTEXT_HEX = (\n    'e2cd291adf58c0735c32090f7eb496356965f3f153c572442118ed25d7b540d0'\n    '2e4bd3198db36ace7c3294437db04efbe367338f3dcfaf4504e2c67da81e9b32'\n)\n\n\ndef main():\n    key = hashlib.sha256(PRIVATE_KEY_HEX.encode('ascii')).digest()\n    ciphertext = bytes.fromhex(CIPHERTEXT_HEX)\n\n    dec = Cipher(algorithms.AES(key), modes.ECB()).decryptor()\n    plaintext = dec.update(ciphertext) + dec.finalize()\n\n    # Validate and remove padding.\n    pad = plaintext[-1]\n\n    if not (1 <= pad <= 32 and plaintext.endswith(bytes([pad]) * pad)):\n        raise ValueError('Invalid padded plaintext; verify key and ciphertext')\n\n    flag = plaintext[:-pad].decode('ascii')\n\n    if not (flag.startswith('Securinets{') and flag.endswith('}')):\n        raise ValueError('Decrypted text is not a valid-format flag')\n\n    print('<FLAG>' + flag + '</FLAG>')\n\n\nif __name__ == '__main__':\n    main()\n\n"
