      {
        "title": "SDR QPSK Pipeline & Reed-Solomon Decoder (solve_final.py)",
        "content": "Script Python lengkap yang memproses sinyal I/Q dari Saleae capture, menyelaraskan frame simbol, mendekode codeword Reed-Solomon, dan merekonstruksi payload flag.",
        "code": "#!/usr/bin/env python3\n\"\"\"Final Silent Tone solver. Run after extracting and coherently combining RF frames.\n\nRequired intermediate files:\n    valid_root47_avg_0_17_sigma25.npy\n    valid_root104_avg_0_22_sigma25.npy\nThe preparation pipeline is documented in Readme.md.\n\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport zlib\n\nimport numpy as np\nfrom scipy.ndimage import uniform_filter1d\n\nfrom rs_ctf import correct, encode, syndromes\nfrom rs_scram import scrambler\n\nINPUTS = (\n    (47, 'valid_root47_avg_0_17_sigma25.npy', 0x2e),\n    (104, 'valid_root104_avg_0_22_sigma25.npy', 0x67),\n)\n\n\ndef demodulate_and_correct(path: str, seed: int) -> bytes:\n    symbols = np.load(path)\n    assert symbols.shape == (1020,), (path, symbols.shape)\n    normalized = symbols / (np.abs(symbols) + 1e-9)\n    phase = np.unwrap(np.angle(uniform_filter1d(normalized**4, size=9, mode='nearest'))) / 4\n    qpsk = normalized * np.exp(-1j * phase + 1j * np.pi / 4)\n    bits = np.stack((qpsk.imag < 0, qpsk.real < 0), axis=-1).astype('uint8').ravel()\n    # Undo interleaver and scrambler, retaining discovered bit ordering/alignment.\n    decoded_bits = np.roll(bits[::-1], 3).reshape(40, 51).T.ravel() ^ scrambler(seed, 5)\n    raw = np.packbits(decoded_bits[::-1]).tobytes()\n    codeword, corrected = correct(raw)\n    if codeword is None or any(syndromes(codeword)) or encode(codeword[:223]) != codeword:\n        raise RuntimeError(f'RS correction failed for {path}')\n    print(f'[+] {path}: RS(255,223) valid; {corrected} byte errors corrected')\n    return codeword\n\n\ndef find_crc_packet(codeword: bytes, expected_part: int) -> tuple[int, bytes]:\n    # Full-length Reed-Solomon code is cyclic: a rotation can still have zero syndromes.\n    for shift in range(len(codeword)):\n        rotated = codeword[shift:] + codeword[:shift]\n        part, length = rotated[:2]\n        if part != expected_part or not 1 <= length <= 217:\n            continue\n        payload = rotated[2:2+length]\n        saved_crc = rotated[2+length:6+length]\n        calc = zlib.crc32(payload) & 0xffffffff\n        if saved_crc == calc.to_bytes(4, 'big'):\n            print(f'[+] part {part}: cyclic shift={shift}; length={length}; CRC32={calc:08x} OK')\n            return shift, payload\n    raise RuntimeError(f'No CRC-valid part {expected_part}')\n\n\ndef decrypt(parts: dict[int, bytes]) -> str:\n    # UIDs: root104 (0x67), root47 (0x2e), root29 (console, 0x1c).\n    key = bytes.fromhex('145d75bf c0f4e5b2 c1e20dc4')\n    ciphertext = parts[1] + parts[2]\n    stream = b''.join(hashlib.sha256(key + i.to_bytes(4, 'big')).digest()\n                      for i in range((len(ciphertext)+31)//32))\n    plaintext = bytes(a ^ b for a, b in zip(ciphertext, stream)).decode('ascii')\n    if not plaintext.startswith('Securinets{') or not plaintext.endswith('}'):\n        raise RuntimeError(f'Decrypted text has unexpected format: {plaintext!r}')\n    return plaintext\n\n\ndef main():\n    parts = {}\n    for root, path, seed in INPUTS:\n        if not Path(path).is_file():\n            raise FileNotFoundError(f'Missing {path}; see Readme.md for preparation')\n        codeword = demodulate_and_correct(path, seed)\n        _, payload = find_crc_packet(codeword, 1 if root == 47 else 2)\n        parts[1 if root == 47 else 2] = payload\n    flag = decrypt(parts)\n    print(f'<FLAG>{flag}</FLAG>')\n\n\nif __name__ == '__main__':\n    main()\n"
      }
