        "title": "Pipeline Inversion & XPRESS Decompressor (solve.py)",
        "content": "Script Python lengkap yang membalik seluruh tahapan transformasi enkripsi: de-alphabet Base64 kustom, pembalikan S-Box nonlinear 768-bit, de-mixing permutasi pairwise, un-doing cumulative sum, dan memanggil fungsi dekompresi XPRESS (format 0x0003) untuk memulihkan 78-byte plaintext flag.",
        "code": "\n#!/usr/bin/env python3\n\"\"\"Reproducible local solver for Encrypt (REV).\n\nReads only the challenge folder. Requires Linux x86-64, Python 3.10+, GCC,\nPython modules from the local reverse-engineering work and payload.bin.\n\nWorkflow: validated outer decoder -> recovered header metadata -> native\nkey-schedule snapshots for all 1000 plausible milliseconds -> inverse of\n96-byte inner transform -> XPRESS literal block decoder -> native forward\nreencryption (exact ciphertext equality).\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport os\nimport subprocess\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nos.chdir(ROOT)\n\n\ndef compile_if_needed(output: str, source: str, extra: list[str] | None = None) -> None:\n    out, src = ROOT / output, ROOT / source\n    if not src.is_file():\n        raise FileNotFoundError(f'Local source missing: {src}')\n    if out.is_file() and out.stat().st_mtime >= src.stat().st_mtime:\n        return\n    args = ['gcc', '-O2', '-Wall', '-Wextra', '-Wno-unused-function']\n    args += extra or []\n    subprocess.run(args + ['-o', str(out), str(src)], check=True, cwd=ROOT)\n\n\ndef unpack_xpress_literals(data: bytes, expected_len: int) -> bytes:\n    \"\"\"Decode the observed Windows XPRESS stream using its 32-bit flag words.\n\n    This CTF sample contains only literal symbols (no match references). For\n    every 32 symbols, a LE uint32 flag word is read MSB-first; bit 0 means\n    the next byte is a literal. The final unused bits may be set to 1.\n    Reject match references rather than silently guessing their semantics.\n    \"\"\"\n    out = bytearray()\n    pos = 0\n    while len(out) < expected_len:\n        if pos + 4 > len(data):\n            raise ValueError('XPRESS: truncated 32-bit flags')\n        flags = int.from_bytes(data[pos:pos + 4], 'little')\n        pos += 4\n        for i in range(31, -1, -1):\n            if len(out) == expected_len:\n                break\n            if (flags >> i) & 1:\n                raise ValueError('XPRESS: unexpected match token in this sample')\n            if pos >= len(data):\n                raise ValueError('XPRESS: truncated literal')\n            out.append(data[pos])\n            pos += 1\n    if pos != len(data):\n        raise ValueError(f'XPRESS: {len(data)-pos} unexpected trailing bytes')\n    return bytes(out)\n\n\ndef main() -> None:\n    if not (ROOT / 'payload.bin').is_file():\n        raise FileNotFoundError('Extract local FPACK resource into payload.bin first')\n    # Build native local probes from the previously audited source if necessary.\n    compile_if_needed('fastbig_native.so', 'fastbig.c', ['-shared', '-fPIC'])\n    compile_if_needed('snapshot_native', 'snapshot_native.c')\n    compile_if_needed('full_encrypt_verify', 'full_encrypt_verify.c')\n\n    from decode_format import decode\n    from header_probe import try_header\n    from vm_probe import seed_to_material\n    from full_inverse import inverse, native_state\n\n    cipher = (ROOT / 'cipher.txt').read_bytes()\n    header, body, trailer = decode(cipher)\n    if len(header) != 14 or len(body) != 96 or len(trailer) != 4:\n        raise RuntimeError('Unexpected encrypted record layout')\n\n    # Under the unmodified binary's normal no-debug and successful compression\n    # path, VM seed=0. This is cross-checked against the recovered timestamp\n    # and size metadata rather than taken as an arbitrary encryption key.\n    metadata = try_header(header, trailer, seed_to_material(0), len(body))\n    seconds = int.from_bytes(metadata[0:8], 'little')\n    plain_len = int.from_bytes(metadata[8:10], 'little')\n    compressed_len = int.from_bytes(metadata[10:12], 'little')\n    entropy = int.from_bytes(metadata[12:14], 'little')\n    print(f'[*] Header: unix_seconds={seconds}, length={plain_len}, '\n          f'compressed={compressed_len}, entropy=0x{entropy:04x}')\n    if seconds != 1792226999 or plain_len != 78 or compressed_len != 90 or entropy != 0x7d9e:\n        raise RuntimeError('Header did not validate against the supplied artifact')\n\n    matches = []\n    for millis in range(1000):\n        recovered = inverse(cipher, native_state(millis))\n        if len(recovered) != compressed_len:\n            continue\n        try:\n            plaintext = unpack_xpress_literals(recovered, plain_len)\n        except ValueError:\n            continue\n        if plaintext.startswith(b'Securinets{') and plaintext.endswith(b'}'):\n            matches.append((millis, plaintext, recovered))\n\n    if len(matches) != 1:\n        raise RuntimeError(f'Expected one verified candidate, got {len(matches)}')\n    millis, flag, recovered = matches[0]\n    assert millis == 725\n    assert len(flag) == 78\n\n    # The native validation harness reads ONLY this local file and packs the\n    # candidate as XPRESS before executing the actual Encrypt function.\n    (ROOT / 'flag_candidate.bin').write_bytes(flag)\n    (ROOT / 'recovered_xpress.bin').write_bytes(recovered)\n    verify = subprocess.run(['./full_encrypt_verify', str(millis)],\n                            capture_output=True, text=True, check=True, cwd=ROOT)\n    rebuilt = bytes.fromhex(verify.stdout.strip())\n    if rebuilt != cipher:\n        raise RuntimeError('Forward verification FAILED: ciphertext differs')\n    print(f'[+] Millisecond recovered: {millis}')\n    print(f'[+] XPRESS literal stream: {recovered[:4].hex()} / '\n          f'{recovered[36:40].hex()} / {recovered[72:76].hex()}')\n    print(f'[+] Ciphertext SHA-256: {hashlib.sha256(cipher).hexdigest()}')\n    print('[+] Exact native forward-encryption verification: PASS (152/152 bytes)')\n    print(f'<FLAG>{flag.decode(\"ascii\")}</FLAG>')\n\n\nif __name__ == '__main__':\n    main()\n"
