        "content": "Emulator Python mandiri untuk menginterpretasikan arsitektur instruction set bytecode kustom (`vm_code.bin`), merekam status register, dan memantau evaluasi branching / equality checks.",
        "code": "from pathlib import Path\nfrom hashlib import sha256\nfrom struct import pack\nfrom collections import Counter\nimport sys,time\ncode=Path(__file__).with_name('vm_code.bin').read_bytes()\nMASK=0xffffffff\n\ndef emulate(inp:bytes,debug=False):\n    stack=[]; ip=0x829; eqs=[];ctr=Counter(); changes=[]\n    cache={}\n    while ip < len(code):\n        pos=ip;op=code[ip];ip+=1;ctr[op]+=1\n        if op==0xa7:\n            v=int.from_bytes(code[ip:ip+4],'little');ip+=4;stack.append((v,0))\n        elif op==0x9a:\n            end,dep1=stack.pop();start,dep2=stack.pop()\n            assert end<1000 and start<1000,(pos, start,end)\n            value=sum(inp[start:end])&MASK\n            dep=(sum(1<<i for i in range(start,min(end,len(inp)))) if end>=start else 0) |dep1|dep2\n            stack.append((value,dep))\n        elif op==0xe3:\n            x,dx=stack.pop();y,dy=stack.pop();stack.append((x&y,dx|dy))\n        elif op==0x94:\n            x,dx=stack.pop();y,dy=stack.pop();stack.append((x^y,dx|dy))\n        elif op==0xb3:\n            sh,ds=stack.pop();v,dv=stack.pop();stack.append(((v<<sh)&MASK if sh<32 else 0,ds|dv))\n        elif op==0xd7:\n            n,dn=stack.pop();\n            if n not in cache:cache[n]=sha256(pack('<I',n)).digest()\n            stack.extend((b,dn) for b in cache[n][::-1])\n        elif op==0x4e:\n            n,dn=stack.pop();\n            assert n>=0 and n<1000\n            data=stack[-n:] if n else []\n            if n: del stack[-n:]\n            stack.append((sum(x for x,d in data)&MASK,dn|sum(0 for i in [])|__import__('functools').reduce(lambda a,b:a|b,(d for x,d in data),0)))\n        elif op==0x6d:\n            a,da=stack.pop();b,db=stack.pop();result=int(a==b);ds=da|db\n            stack.append((result,ds));eqs.append((pos,result,ds,a,b,len(stack)))\n        elif op==0xf2:\n            x,dx=stack.pop();y,dy=stack.pop();stack.append(((x+y)&MASK,dx|dy))\n        elif op==0x3e:stack.pop()\n        elif op==0x55:pass\n        elif op==0x58:\n            target=int.from_bytes(code[ip:ip+4],'little');ip+=4\n            cond,dc=stack.pop()\n            changes.append(('JZ',pos,target,cond,dc,len(stack)))\n            if not cond:ip=target\n        elif op==0x2f:\n            val,dep=stack.pop()\n            if debug:print('PRINT',chr(val&255),pos)\n        elif op==0x00:break\n        else:raise ValueError((hex(pos),hex(op),len(stack)))\n    return stack,eqs,ctr,changes\n\nif __name__=='__main__':\n   st=time.monotonic(); inp=(sys.argv[1].encode() if len(sys.argv)>1 else b'A'*56);\n   v,e,c,ch=emulate(inp,True)\n   print('elapsed',time.monotonic()-st,'stack',v,'eqs',len(e),'eq_true',sum(x[1] for x in e),'changes',ch)\n   print('Eqs summaries:')\n   for x in e: print(hex(x[0]),x[1],x[2].bit_count(),[i for i in range(56) if (x[2]>>i)&1],x[3],x[4],x[5])\n"
